[RegisterCard(typeof(WeiDongZhuoCardPool), FullPublicEntry = "YJCM_CARD_WEI_DONG_ZHUO_DI_LU")]
public sealed class WeiDongZhuoDiLu : WeiDongZhuoCard
{
    private static readonly string VoicePath = Path.Combine(
        Path.GetDirectoryName(typeof(WeiDongZhuoDiLu).Assembly.Location)!,
        "Voice", "Bank", "Assets", "fang_ju.wav");

    public WeiDongZhuoDiLu()
        : base(1, CardType.Power, CardRarity.Uncommon, TargetType.Self) { }

    // 为描述中的 [虚弱]/[易伤]/[脆弱] 提供悬浮提示
    protected override IEnumerable<IHoverTip> AdditionalHoverTips =>
        [HoverTipFactory.FromPower<WeakPower>(),
